[Petal] Event Monitor

- basically count event trigger
- hook event
- e.g.
<html><head><script src="petal-evtmonitor.js"></script></head>
      <body><button id="test">Test</button></body>
      <script>
      $petal.evtmonitor.switchOn();
      function click(evt) {
        console.log(evt.target.outerText, $petal.evtmonitor.count(evt.target, click));
      }
      $('#test').click(click);
      </script></html>
